const __pageData = JSON.parse('{"title":"阿里云OSS与参数配置化","description":"顺着上一篇本地存储的三个问题往下走，先把阿里云与对象存储 OSS 讲清楚，再按第三方服务的通用思路走一遍开通与使用的步骤，然后拿官方 SDK 改造出的工具类接进 Tlias（上传完返回图片 URL），最后治一治「参数写死在代码里」的毛病，把逐个注入与批量绑定两种参数配置化方式摆在一起对比","frontmatter":{"title":"阿里云OSS与参数配置化","published":"2026-09-29T00:00:00.000Z","description":"顺着上一篇本地存储的三个问题往下走，先把阿里云与对象存储 OSS 讲清楚，再按第三方服务的通用思路走一遍开通与使用的步骤，然后拿官方 SDK 改造出的工具类接进 Tlias（上传完返回图片 URL），最后治一治「参数写死在代码里」的毛病，把逐个注入与批量绑定两种参数配置化方式摆在一起对比","tags":["JavaWeb","SpringBoot","部署"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-73-aliyun-oss-config(1).webp","order":73,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/73-阿里云OSS与参数配置化.md","filePath":"posts/学习文档/JavaWeb学习笔记/73-阿里云OSS与参数配置化.md"}');
